#### `server.js`

```js
const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');

const DATA_PATH = path.join(__dirname, 'data', 'data.json');

const app = express();
app.use(cors());
app.use(bodyParser.json());
app.use(express.static(path.join(__dirname, 'public')));

// Read data file or initialize
function readData() {
  try {
    const raw = fs.readFileSync(DATA_PATH);
    return JSON.parse(raw);
  } catch {
    return { tasks: [] };
  }
}
// Write data file
function writeData(data) {
  fs.writeFileSync(DATA_PATH, JSON.stringify(data, null, 2));
}

// GET all tasks with contacts and logs
app.get('/api/tasks', (req, res) => {
  const data = readData();
  res.json(data.tasks);
});

// POST create new task {name}
app.post('/api/tasks', (req, res) => {
  const { name } = req.body;
  if (!name || !name.trim()) return res.status(400).json({ error: 'Task name required' });
  const data = readData();
  const newTask = { id: uuidv4(), name: name.trim(), contacts: [] };
  data.tasks.push(newTask);
  writeData(data);
  res.json(newTask);
});

// POST add contact to task {name}
app.post('/api/tasks/:taskId/contacts', (req, res) => {
  const { taskId } = req.params;
  const { name } = req.body;
  if (!name || !name.trim()) return res.status(400).json({ error: 'Contact name required' });
  const data = readData();
  const task = data.tasks.find(t => t.id === taskId);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  const newContact = {
    id: uuidv4(),
    name: name.trim(),
    progress: '',
    logs: []
  };
  task.contacts.push(newContact);
  writeData(data);
  res.json(newContact);
});

// POST add log to contact {type:'call'|'note', note}
app.post('/api/tasks/:taskId/contacts/:contactId/logs', (req, res) => {
  const { taskId, contactId } = req.params;
  const { type, note } = req.body;
  if (!type || !note || !note.trim()) return res.status(400).json({ error: 'Type and note required' });
  const data = readData();
  const task = data.tasks.find(t => t.id === taskId);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  const contact = task.contacts.find(c => c.id === contactId);
  if (!contact) return res.status(404).json({ error: 'Contact not found' });
  const logEntry = {
    timestamp: Date.now(),
    type,
    note: note.trim()
  };
  contact.logs.push(logEntry);
  writeData(data);
  res.json(logEntry);
});

// PATCH update contact progress {progress}
app.patch('/api/tasks/:taskId/contacts/:contactId/progress', (req, res) => {
  const { taskId, contactId } = req.params;
  const { progress } = req.body;
  if (typeof progress !== 'string') return res.status(400).json({ error: 'Progress is required' });
  const data = readData();
  const task = data.tasks.find(t => t.id === taskId);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  const contact = task.contacts.find(c => c.id === contactId);
  if (!contact) return res.status(404).json({ error: 'Contact not found' });
  contact.progress = progress.trim();
  writeData(data);
  res.json({ success: true });
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

